SELECT medicare3_1.nppes_provider_country AS nppes_provider_country,   medicare3_1.nppes_provider_state AS nppes_provider_state,   SUM(medicare3_1.average_medicare_allowed_amt) AS sum_average_medicare_allowed_amt_ok FROM medicare3_1 WHERE (medicare3_1.provider_type IN ('Physical Medicine and Rehabilitation', 'Physical Therapist')) GROUP BY medicare3_1.nppes_provider_country,   medicare3_1.nppes_provider_state;
